def f(xs):
    if len(xs) < 2:
        return []
    return xs[max(0, xs[0] + 1):max(0, xs[1] + 2)]

def f(xs):
    out = []
    for x in xs:
        if not out or x > out[-1]:
            out.append(x)
    return out

def f(xs):
    if not xs:
        return []
    unique = list(dict.fromkeys(xs))
    unique.insert(max(0, xs[0] - 1), xs[-1])
    return unique

def f(xs):
    if not xs:
        return []
    left = max(0, xs[0])
    right = max(0, xs[-1])
    return xs[left:max(left, len(xs) - right)]
